// ---------------- DIAGNÓSTICO V4.3.3 ----------------
const OKEO_APP_VERSION='6.3.0';
const DIAG_KEY='okeo_diagnostics_v433';
const OKEO_SUITE_APP="OKEO Operação";
const OKEO_SUITE_ALLOWED=["inventario", "nf", "movimentos"];
const OKEO_SUITE_DEFAULT="inventario";
function suiteModuleAllowed(name){return OKEO_SUITE_ALLOWED.includes(name)}
function applySuiteScope(){
 document.querySelectorAll('[data-module]').forEach(el=>{const m=el.dataset.module;if(m&&!suiteModuleAllowed(m))el.style.display='none'});
 const badge=document.getElementById('suiteHomeBadge');
 if(badge)badge.innerHTML='<button onclick="window.openSuiteHub&&window.openSuiteHub()" style="border:0;border-radius:999px;padding:8px 12px;background:#1d416b;color:white;font-weight:700;cursor:pointer">⌂ OKEO Hub</button>';
}
window.openSuiteHub=async function(){
 try{const j=await getBackend('suite_config_get');if(j&&j.ok&&j.apps&&j.apps.hub)location.href=j.apps.hub;else alert('URL do OKEO Hub ainda não configurada na Base Central.')}catch(e){alert('Não foi possível abrir o Hub.')}
};
const MODULE_NAMES={
 inventario:'Inventário',nf:'Entrada por NF',movimentos:'Movimentações',
 dashboard:'Relatórios',financeiro:'Fluxo de Caixa',dre:'DRE',
 faturamento:'Faturamento / Vendas',produtos:'Curva ABC',reposicao:'Reposição Inteligente',
 fornecedores:'Fornecedores',grupos:'Grupos de Demanda',horarios:'Dias / Horários',
 mensal:'Histórico Mensal',cashback:'Cashback / Energia',fiscal:'Cadastro Fiscal',
 integracao:'Integração / API',acessos:'Controle de Acesso',diagnostico:'Saúde do Sistema',inteligencia:'Inteligência de Estoque',gestao:'Gestão Executiva',dados:'Política de Dados',inteligencia:'Inteligência de Estoque'
};
let sessionDiagnosticErrors=0;
let activeModuleForDiagnostics='startup';
let moduleHealth={};

function safeDiagText(v){
 let s=String(v??'');
 s=s.replace(/(password|senha|token|authorization)\s*[:=]\s*[^,\s}]+/gi,'$1=[REMOVIDO]');
 s=s.replace(/Bearer\s+[A-Za-z0-9._-]+/gi,'Bearer [REMOVIDO]');
 return s.slice(0,1800);
}
function getDiagnostics(){
 try{
   const a=JSON.parse(localStorage.getItem(DIAG_KEY)||'[]');
   return Array.isArray(a)?a:[];
 }catch(e){return []}
}
function saveDiagnostics(a){
 try{localStorage.setItem(DIAG_KEY,JSON.stringify(a.slice(-100)))}catch(e){}
}
function recordDiagnostic(type,message,detail='',moduleName=''){
 const item={
   time:new Date().toISOString(),
   version:OKEO_APP_VERSION,
   module:moduleName||activeModuleForDiagnostics||'desconhecido',
   type:safeDiagText(type),
   message:safeDiagText(message),
   detail:safeDiagText(detail),
   url:location.pathname
 };
 const a=getDiagnostics();a.push(item);saveDiagnostics(a);
 sessionDiagnosticErrors++;
 moduleHealth[item.module]={status:'error',last:item.time,message:item.message};
 updateHealthIndicator();
 try{renderDiagnostics()}catch(e){}
 return item;
}
function markModuleHealthy(name){
 if(!name)return;
 const prev=moduleHealth[name];
 if(!prev||prev.status!=='error')moduleHealth[name]={status:'ok',last:new Date().toISOString(),message:'OK'};
 updateHealthIndicator();
}
function updateHealthIndicator(){
 const errors=getDiagnostics();
 const el=document.getElementById('healthCardStatus');
 if(el)el.textContent=errors.length?`${errors.length} erro(s) registrado(s)`:'Sistema sem erros registrados';
}
window.addEventListener('error',e=>{
 recordDiagnostic('javascript',e.message||'Erro JavaScript',
   `${e.filename||''}:${e.lineno||''}:${e.colno||''}\n${e.error&&e.error.stack?e.error.stack:''}`);
});
window.addEventListener('unhandledrejection',e=>{
 const r=e.reason;
 recordDiagnostic('promise',r&&r.message?r.message:'Promise rejeitada',
   r&&r.stack?r.stack:String(r||''));
});

async function monitoredModuleRun(name,fn){
 activeModuleForDiagnostics=name;
 const started=perfStart(name);
 try{
   const result=await fn();
   markModuleHealthy(name);
   return result;
 }catch(e){
   recordDiagnostic('module',e&&e.message?e.message:'Falha no módulo',
     `${e&&e.stack?e.stack:''}\nTempo até falha: ${Math.round(performance.now()-started)} ms`,name);
   const box=document.getElementById('moduleLoading');
   if(box){box.style.display='flex';box.textContent=`Falha em ${MODULE_NAMES[name]||name}. Consulte Saúde do Sistema.`}
   throw e;
 }finally{
   perfEnd(name,started);
   activeModuleForDiagnostics='idle';
 }
}
function diagnosticsSnapshot(){
 const errs=getDiagnostics();
 return {
   app:'OKEO Gestão',
   version:OKEO_APP_VERSION,
   generatedAt:new Date().toISOString(),
   browser:navigator.userAgent,
   online:navigator.onLine,
   moduleHealth,
   errors:errs
 };
}
function renderDiagnostics(){
 const errs=getDiagnostics(),overall=document.getElementById('healthOverall');
 if(overall){
   overall.textContent=errs.length?'Atenção':'Tudo OK';
   overall.className='healthPill '+(errs.length?'warn':'ok');
 }
 const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};
 set('diagSessionErrors',sessionDiagnosticErrors);
 set('diagStoredErrors',errs.length);
 set('diagLastError',errs.length?new Date(errs[errs.length-1].time).toLocaleString('pt-BR'):'Nenhum');

 const mods=document.getElementById('moduleHealthList');
 if(mods){
   mods.innerHTML=Object.keys(MODULE_NAMES).map(k=>{
     const h=moduleHealth[k]||{status:'unknown',message:'Ainda não testado'};
     const cls=h.status==='error'?'bad':h.status==='ok'?'ok':'unknown';
     const label=h.status==='error'?'Falha':h.status==='ok'?'OK':'Não testado';
     return `<div class="healthModuleRow"><span><b>${MODULE_NAMES[k]}</b><br><small>${safeDiagText(h.message||'')}</small></span><span class="healthPill ${cls}">${label}</span></div>`;
   }).join('');
 }
 const list=document.getElementById('diagnosticErrors');
 if(list){
   list.innerHTML=errs.slice().reverse().slice(0,40).map(x=>`<div class="diagError">
     <b>${MODULE_NAMES[x.module]||x.module} • ${x.type}</b>
     <small>${new Date(x.time).toLocaleString('pt-BR')} • V${x.version}</small>
     <div>${safeDiagText(x.message)}</div>
     ${x.detail?`<pre>${safeDiagText(x.detail)}</pre>`:''}
   </div>`).join('')||'<div class="healthEmpty">Nenhum erro registrado.</div>';
 }
 updateHealthIndicator();
}
function downloadDiagnostics(){
 const blob=new Blob([JSON.stringify(diagnosticsSnapshot(),null,2)],{type:'application/json'});
 const a=document.createElement('a');a.href=URL.createObjectURL(blob);
 a.download='OKEO_Diagnostico_'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';
 a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}

// ---------------- RESILIÊNCIA / PERFORMANCE V4.4.0 ----------------
const OKEO_BUILD='6.3.0';
const OKEO_SCHEMA_VERSION=4;
const OKEO_BOOT_KEY='okeo_boot_v440';
const OKEO_SAFE_MODE_KEY='okeo_safe_mode_v440';
const OKEO_LAST_VERSION_KEY='okeo_last_version';

let reportGeneration={};
let systemSafeMode=localStorage.getItem(OKEO_SAFE_MODE_KEY)==='1';

function nextReportGeneration(name){
 reportGeneration[name]=(reportGeneration[name]||0)+1;
 return reportGeneration[name];
}
function isLatestReport(name,generation){
 return reportGeneration[name]===generation;
}
function sleep(ms){return new Promise(r=>setTimeout(r,ms))}

function markBootStart(){
 try{
   const now=Date.now(),raw=JSON.parse(localStorage.getItem(OKEO_BOOT_KEY)||'{}');
   const recent=raw.time&&now-raw.time<60000;
   const failures=recent?(Number(raw.failures)||0)+1:1;
   localStorage.setItem(OKEO_BOOT_KEY,JSON.stringify({time:now,failures,completed:false}));
   if(failures>=3){
     systemSafeMode=true;
     localStorage.setItem(OKEO_SAFE_MODE_KEY,'1');
   }
 }catch(e){}
}
function markBootComplete(){
 try{
   localStorage.setItem(OKEO_BOOT_KEY,JSON.stringify({time:Date.now(),failures:0,completed:true}));
 }catch(e){}
}
function resetSafeMode(){
 systemSafeMode=false;
 localStorage.removeItem(OKEO_SAFE_MODE_KEY);
 localStorage.removeItem(OKEO_BOOT_KEY);
 renderDiagnostics?.();
}
markBootStart();

async function storageHealth(){
 try{
   if(!navigator.storage||!navigator.storage.estimate)return null;
   return await Promise.race([
     navigator.storage.estimate().then(e=>{const usage=Number(e.usage)||0,quota=Number(e.quota)||0,pct=quota?usage/quota*100:0;return{usage,quota,pct}}),
     new Promise(res=>setTimeout(()=>res({usage:0,quota:0,pct:0,timeout:true}),1000))
   ]);
 }catch(e){return null}
}

function bytesHuman(n){
 const u=['B','KB','MB','GB'];let i=0,v=Number(n)||0;
 while(v>=1024&&i<u.length-1){v/=1024;i++}
 return v.toFixed(i?1:0)+' '+u[i];
}
async function renderStorageHealth(){
 const h=await storageHealth();
 const el=document.getElementById('storageHealth');
 if(!el)return;
 if(!h){el.textContent='Armazenamento: indisponível';return}if(h.timeout){el.textContent='Armazenamento: OK';el.className='storageHealth ok';return} if(h.timeout){el.textContent='Armazenamento: OK';el.className='storageHealth ok';return}
 el.textContent=`Armazenamento: ${bytesHuman(h.usage)} de ${bytesHuman(h.quota)} (${h.pct.toFixed(1).replace('.',',')}%)`;
 el.className='storageHealth '+(h.pct>=85?'bad':h.pct>=70?'warn':'ok');
 if(h.pct>=85)recordDiagnostic?.('storage','Armazenamento do navegador acima de 85%',el.textContent,'diagnostico');
}
async function cleanupOldCaches(){
 if(!('caches' in window))return;
 try{
   const keep='okeo-gestao-v4-4-0',keys=await caches.keys();
   await Promise.all(keys.filter(k=>k.startsWith('okeo-gestao-')&&k!==keep).map(k=>caches.delete(k)));
 }catch(e){}
}
function migrateVersion(){
 try{
   const old=localStorage.getItem(OKEO_LAST_VERSION_KEY);
   if(old!==OKEO_BUILD){
     localStorage.setItem(OKEO_LAST_VERSION_KEY,OKEO_BUILD);
     // Remove somente marcadores/cache efêmeros; nunca apaga estoque/cadastros.
     ['okeo_historical_seed_version','okeo_backend_migrated_v417'].forEach(k=>localStorage.removeItem(k));
     setTimeout(cleanupOldCaches,800);
   }
 }catch(e){}
}
migrateVersion();

