const SERVER_ANALYTICS_TTL=5*60*1000;
const backendInflight=new Map();
async function backendAnalytics(action,params={}){
 const token=localStorage.getItem('okeo_auth_token_v39')||'';if(!token)throw new Error('AUTH_REQUIRED');
 const key='server:'+action+':'+JSON.stringify(params),cached=await idbGet(key);
 const ttl=action==='sales_report'?30000:(action==='sales_filter_options'?1800000:900000);
 if(cached&&cached.savedAt&&Date.now()-cached.savedAt<ttl)return cached.data;
 if(backendInflight.has(key)){if(cached&&cached.data)return cached.data;return backendInflight.get(key)}
 const promise=(async()=>{
   const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),7000);
   try{
     const qs=new URLSearchParams({action,token,...params,_ts:String(Date.now())});
     const r=await fetch(OKEO_DEFAULT_BACKEND+'?'+qs.toString(),{cache:'no-store',signal:ctrl.signal});
     const j=await r.json();if(!j||!j.ok)throw new Error((j&&j.error)||'Analytics backend');
     await idbPut(key,{savedAt:Date.now(),data:j});return j;
   }finally{clearTimeout(timer);backendInflight.delete(key)}
 })();
 backendInflight.set(key,promise);
 if(cached&&cached.data){promise.catch(()=>{});return cached.data}
 return promise;
}

function loadReportJson(key,url){
 if(reportLoads[key])return reportLoads[key];
 reportLoads[key]=(async()=>{
   const cacheKey='json:'+key,hit=await idbGet(cacheKey);
   if(hit&&hit.data){
     // Atualiza em segundo plano sem bloquear.
     fetch(url+'?v=620',{cache:'no-cache'}).then(r=>r.ok?r.json():null).then(data=>{if(data)idbPut(cacheKey,{savedAt:Date.now(),data})}).catch(()=>{});
     return hit.data;
   }
   const r=await fetch(url+'?v=620',{cache:'force-cache'});if(!r.ok)throw new Error(url);
   const data=await r.json();await idbPut(cacheKey,{savedAt:Date.now(),data});return data;
 })();
 return reportLoads[key];
}
