function salesMetrics(unit='',from='',to=''){
 const ck=fastCacheKey(['sales428',unit,from,to]);
 if(metricCache.has(ck))return metricCache.get(ck);

 let revenue=0,unitsSold=0,tickets=0,rows=[];
 const canUseAgg=optimizedHistoryReady&&historicalUnitDayRows.length&&(!from||from>='2026-04-01')&&(!to||to<='2026-07-31');

 if(canUseAgg){
   historicalUnitDayRows.forEach(x=>{
     if(from&&x.date<from)return;if(to&&x.date>to)return;
     if(unit&&unit!==TOTAL_UNIT&&x.unit!==unit)return;
     revenue+=Number(x.value)||0;unitsSold+=Number(x.qty)||0;tickets+=Number(x.tickets)||0;
   });
   // detailed rows only when caller needs them later; use product-day aggregate as lightweight substitute
   rows=historicalProductDayRows.filter(x=>(!from||x.date>=from)&&(!to||x.date<=to)&&(!unit||unit===TOTAL_UNIT||x.unit===unit)).map(x=>({
     datetime:x.date+' 12:00:00',unit:x.unit,code:x.code,product:x.product,qty:x.qty,value:x.value,source:'HIST_AGG'
   }));
 }else{
   rows=analysisSalesRows().filter(x=>{
     const d=saleDateKey(x.datetime),isCd=String(x.unit||'').toLowerCase().includes('cd - estoque central');
     const unitOk=!unit||unit===TOTAL_UNIT?!isCd:x.unit===unit;
     return unitOk&&(!from||d>=from)&&(!to||d<=to);
   });
   revenue=rows.reduce((a,x)=>a+(Number(x.value)||0),0);
   unitsSold=rows.reduce((a,x)=>a+(Number(x.qty)||0),0);
   tickets=new Set(rows.map(x=>x.unit+'|'+normalizeDateTime(x.datetime))).size;
 }

 let cmv=0;
 // CMV is unavailable historically until purchase costs are present; keep current logic for new/local sales.
 if(!canUseAgg){
   rows.forEach(x=>{const p=saleMasterProduct(x),e=p?p.ean:(x.ean||x.code);if(e)cmv+=(Number(x.qty)||0)*(Number(gs(x.unit,e).avgCost)||0)});
 }
 const result={rows,revenue,unitsSold,tickets,avg:tickets?revenue/tickets:0,cmv};
 metricCache.set(ck,result);return result;
}
function renderSalesHistory(){if(document.getElementById('tab-faturamento')?.style.display!=='none')return runSalesSearch(false)}
function productMetrics(unit='',from='',to=''){
 const cacheKey=fastCacheKey(['productMetricsV427',unit,from,to]);
 if(metricCache.has(cacheKey))return metricCache.get(cacheKey);

 const map={};
 function addRow(code,product,qty,value,sourceUnit){
   const p=masterProduct(code)||PRODUCTS.find(pp=>String(pp.produto||'').trim().toLowerCase()===String(product||'').trim().toLowerCase());
   const canonicalCode=p?norm(p.ean):(code||product||'SEM');
   const canonicalName=p?p.produto:(product||('EAN '+code));
   const key=canonicalCode||canonicalName;
   if(!map[key])map[key]={code:canonicalCode,product:canonicalName,qty:0,revenue:0,cmv:0};
   const m=map[key];
   m.qty+=Number(qty)||0;
   m.revenue+=Number(value)||0;
   const e=p?p.ean:code;
   if(e&&sourceUnit)m.cmv+=(Number(qty)||0)*(Number(gs(sourceUnit,e).avgCost)||0);
 }

 // Historical Apr-Jul: use pre-aggregated rows (far fewer records).
 const hist=abcHistoricalRows(unit,from,to);
 if(hist){
   hist.forEach(x=>addRow(x.code,x.product,x.qty,x.value,x.unit));
 }

 // New/manual/API sales outside historical seed: use raw rows, excluding duplicated seed source.
 salesRows.forEach(x=>{
   if(String(x.source||'')==='HISTORICO_ABR_JUL_2026')return;
   const d=saleDateKey(x.datetime);
   if(!d||from&&d<from||to&&d>to)return;
   if(String(x.unit||'').toLowerCase().includes('cd - estoque central'))return;
   if(unit&&unit!==TOTAL_UNIT&&x.unit!==unit)return;
   addRow(x.code||x.ean,x.product,x.qty,x.value,x.unit);
 });

 const arr=Object.values(map);
 const totalRevenue=arr.reduce((a,y)=>a+y.revenue,0);
 const totalCmv=arr.reduce((a,y)=>a+y.cmv,0);
 arr.forEach(x=>{
   x.margin=x.revenue-x.cmv;
   x.salesPct=totalRevenue?x.revenue/totalRevenue*100:0;
   x.cmvPct=totalCmv?x.cmv/totalCmv*100:0;
 });
 arr.sort((a,b)=>b.revenue-a.revenue);

 let acc=0;
 arr.forEach(x=>{
   const before=acc;
   acc+=x.salesPct;
   x.accPct=acc;
   x.abc=before<80?'A':before<95?'B':'C';
 });

 const result={arr,totalRevenue,totalCmv};
 metricCache.set(cacheKey,result);
 return result;
}
function abcClassSummary(arr,totalRevenue){
 const out={A:{count:0,revenue:0},B:{count:0,revenue:0},C:{count:0,revenue:0}};
 arr.forEach(x=>{const g=out[x.abc]||out.C;g.count++;g.revenue+=Number(x.revenue)||0});
 const totalProducts=arr.length;
 Object.keys(out).forEach(k=>{
   out[k].productPct=totalProducts?out[k].count/totalProducts*100:0;
   out[k].revenuePct=totalRevenue?out[k].revenue/totalRevenue*100:0;
 });
 return out;
}
function renderAbcSummary(pm){
 const el=document.getElementById('abcSummary');if(!el)return;
 const abc=abcClassSummary(pm.arr,pm.totalRevenue);
 el.innerHTML=['A','B','C'].map(k=>{
   const x=abc[k];
   return `<div class="abcSummaryCard abc${k}">
     <div class="abcSummaryClass">CURVA ${k}</div>
     <div class="abcSummaryNumber">${x.count.toLocaleString('pt-BR')}</div>
     <div class="abcSummaryLabel">produtos • ${x.productPct.toFixed(1).replace('.',',')}% do mix</div>
     <div class="abcSummaryRevenue">${brl(x.revenue)}</div>
     <div class="abcSummaryLabel">${x.revenuePct.toFixed(1).replace('.',',')}% do faturamento total</div>
   </div>`;
 }).join('');
}
