 document.getElementById('productTable').innerHTML=visible.map(x=>`<div class="abcrow abc${x.abc}"><div><b>${x.product}</b><br><small>${x.code||''} • ${Number(x.qty||0).toLocaleString('pt-BR')} un • margem ${brl(x.margin)}</small></div><div><b>${brl(x.revenue)}</b><br><small>${x.salesPct.toFixed(1).replace('.',',')}% venda</small></div><div><b>${brl(x.cmv)}</b><br><small>${x.cmvPct.toFixed(1).replace('.',',')}% CMV</small></div><div class="abcClass">${x.abc}<br><small>${x.accPct.toFixed(1).replace('.',',')}%</small></div></div>`).join('')||'<small>Sem vendas no período selecionado.</small>';
