// ---------------- DEMANDA POR DIA / HORÁRIO ----------------
function salesDateObj(v){
 const s=String(v||'').trim();
 let m=s.match(/(\d{2})[\/\-](\d{2})[\/\-](\d{4})[ T](\d{1,2}):(\d{2})/);
 if(m)return new Date(Number(m[3]),Number(m[2])-1,Number(m[1]),Number(m[4]),Number(m[5]));
 m=s.match(/(\d{4})[\/\-](\d{2})[\/\-](\d{2})[ T](\d{1,2}):(\d{2})/);
 if(m)return new Date(Number(m[1]),Number(m[2])-1,Number(m[3]),Number(m[4]),Number(m[5]));
 const d=new Date(s);return isNaN(d)?null:d;
}
const DAY_NAMES=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const HOUR_BUCKETS=['00-05','06-08','09-11','12-14','15-17','18-20','21-23'];
function hourBucket(h){if(h<=5)return'00-05';if(h<=8)return'06-08';if(h<=11)return'09-11';if(h<=14)return'12-14';if(h<=17)return'15-17';if(h<=20)return'18-20';return'21-23'}
function timeRows(){
 const unit=document.getElementById('timeUnit').value||TOTAL_UNIT,ean=selectedTimeEan;
 if(optimizedHistoryReady&&historicalTimeRows.length){
   return historicalTimeRows.filter(x=>{
     if(unit&&unit!==TOTAL_UNIT&&x.unit!==unit)return false;
     if(ean){
       const p=masterProduct(x.code)||PRODUCTS.find(pp=>String(pp.produto||'').trim().toLowerCase()===String(x.product||'').trim().toLowerCase());
       const e=norm(p?p.ean:x.code);if(e!==ean)return false;
     }
     return true;
   }).map(x=>({agg:true,unit:x.unit,code:x.code,product:x.product,qty:x.qty,dow:x.dow,bucket:x.bucket}));
 }
 return analysisSalesRows().filter(x=>{
   const p=saleMasterProduct(x),e=norm(p?p.ean:(x.ean||x.code));
   return (!unit||unit===TOTAL_UNIT||x.unit===unit)&&(!ean||e===ean);
 });
}
function renderTimeAnalysis(){
 fillAnalysisUnitSelect('timeUnit');
 const rows=timeRows(),days={},hours={},heat={};
 DAY_NAMES.forEach(d=>{days[d]=0;heat[d]={};HOUR_BUCKETS.forEach(h=>heat[d][h]=0)});HOUR_BUCKETS.forEach(h=>hours[h]=0);
 rows.forEach(x=>{let day,hb;if(x.agg){day=DAY_NAMES[(Number(x.dow)+1)%7];hb=x.bucket}else{const d=salesDateObj(x.datetime);if(!d)return;day=DAY_NAMES[d.getDay()];hb=hourBucket(d.getHours())}const q=Number(x.qty)||0;days[day]+=q;hours[hb]+=q;heat[day][hb]+=q});
 const pd=Object.entries(days).sort((a,b)=>b[1]-a[1])[0]||['-',0],ph=Object.entries(hours).sort((a,b)=>b[1]-a[1])[0]||['-',0];
 document.getElementById('peakDay').textContent=pd[0];document.getElementById('peakHour').textContent=ph[0];document.getElementById('peakDayQty').textContent=pd[1].toLocaleString('pt-BR');document.getElementById('peakHourQty').textContent=ph[1].toLocaleString('pt-BR');
 document.getElementById('weekdayTable').innerHTML=Object.entries(days).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="timerow"><b>${k}</b><span>${v.toLocaleString('pt-BR')} un</span></div>`).join('');
 document.getElementById('hourTable').innerHTML=Object.entries(hours).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="timerow"><b>${k}h</b><span>${v.toLocaleString('pt-BR')} un</span></div>`).join('');
 const max=Math.max(1,...Object.values(heat).flatMap(x=>Object.values(x)));
 let t='<div class="heatwrap"><table class="heattable"><tr><th>Dia</th>'+HOUR_BUCKETS.map(h=>`<th>${h}</th>`).join('')+'</tr>';
 DAY_NAMES.forEach(d=>{t+='<tr><th>'+d+'</th>'+HOUR_BUCKETS.map(h=>{const v=heat[d][h],lvl=Math.min(5,Math.ceil(v/max*5));return `<td class="heat${lvl}">${v}</td>`}).join('')+'</tr>'});t+='</table></div>';document.getElementById('heatmapTable').innerHTML=t;
}
(document.getElementById('timeProductSearch')||{}).oninput=()=>{const q=document.getElementById('timeProductSearch').value.toLowerCase(),uniq={};PRODUCTS.forEach(p=>{const e=norm(p.ean);if(e&&!uniq[e])uniq[e]=p});const a=Object.values(uniq).filter(p=>q&&(p.produto.toLowerCase().includes(q)||norm(p.ean).includes(q))).slice(0,12);document.getElementById('timeProductMatches').innerHTML=a.map(p=>`<button class="gray tagbtn" onclick="selectTimeProduct('${norm(p.ean)}','${encodeURIComponent(p.produto)}')">${p.produto}</button>`).join('')};
window.selectTimeProduct=(e,n)=>{selectedTimeEan=e;document.getElementById('timeProductSearch').value=decodeURIComponent(n);document.getElementById('timeProductMatches').innerHTML='';renderTimeAnalysis()}
