 doc.autoTable({startY:25,head:[['Fornecedor','Condomínio','EAN','Produto','Média sem.','Pico','Mín.','Máx.','Atual','Repor']],body,styles:{fontSize:7,cellPadding:1.5},headStyles:{fillColor:[23,54,93]},columnStyles:{3:{cellWidth:55}}});
