// ---------------- REPOSIÇÃO INTELIGENTE / FORNECEDORES ----------------
let supplierMap={};
let lastReplenishment=[];

function supplierFor(ean){
 const n=norm(ean);
 return supplierMap[n]||'SEM FORNECEDOR';
}
function saveSupplierMap(){
 persistState('supplierMap',supplierMap);
}
function weekStart(dateStr){
 let s=String(dateStr||'').slice(0,10),d=new Date(s+'T12:00:00');
 if(isNaN(d))return '';
 let day=(d.getDay()+6)%7;
 d.setDate(d.getDate()-day);
 return d.toISOString().slice(0,10);
}
function cutoffDate(weeks){
 const d=new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate()-(Number(weeks)*7));
 return d.toISOString().slice(0,10);
}
function currentStockFor(unit,ean){
 return Number(gs(unit,ean).qty)||0;
}

function salesForReplenishment(weeks,unitFilter){
 const end='2026-07-31';
 const endD=new Date(end+'T12:00:00'),cut=new Date(endD);cut.setDate(cut.getDate()-weeks*7+1);
 const cutoff=`${cut.getFullYear()}-${String(cut.getMonth()+1).padStart(2,'0')}-${String(cut.getDate()).padStart(2,'0')}`;
 const map={};

 if(optimizedHistoryReady&&historicalWeeklyRows.length){
   historicalWeeklyRows.forEach(x=>{
     if(x.week<cutoff||x.week>end)return;
     if(unitFilter&&unitFilter!==TOTAL_UNIT&&x.unit!==unitFilter)return;
     const p=masterProduct(x.code)||PRODUCTS.find(pp=>String(pp.produto||'').trim().toLowerCase()===String(x.product||'').trim().toLowerCase());
     const ean=norm(p?p.ean:x.code);if(!ean)return;
     const key=x.unit+'|'+ean;
     if(!map[key])map[key]={unit:x.unit,ean,product:p?p.produto:x.product,weeks:{},total:0};
     map[key].weeks[x.week]=(map[key].weeks[x.week]||0)+Number(x.qty||0);
     map[key].total+=Number(x.qty||0);
   });
   return map;
 }

 // fallback
 analysisSalesRows().forEach(x=>{
   const date=saleDateKey(x.datetime);if(!date||date<cutoff||date>end)return;
   if(String(x.unit||'').toLowerCase().includes('cd - estoque central'))return;
   if(unitFilter&&unitFilter!==TOTAL_UNIT&&x.unit!==unitFilter)return;
   const p=saleMasterProduct(x),ean=norm(p?p.ean:(x.ean||x.code));if(!ean)return;
   const key=x.unit+'|'+ean;
   if(!map[key])map[key]={unit:x.unit,ean,product:(p?p.produto:x.product)||('EAN '+ean),weeks:{},total:0};
   const wk=weekStart(date),q=Number(x.qty)||0;
   map[key].weeks[wk]=(map[key].weeks[wk]||0)+q;map[key].total+=q;
 });
 return map;
}
function replenishmentUnits(unitFilter){
 if(unitFilter&&unitFilter!==TOTAL_UNIT)return [unitFilter];
 return allSalesUnits();
}
function replenishmentProductsForUnit(unit){
 const uniq={};
 PRODUCTS.forEach(p=>{
   const e=norm(p.ean);if(!e)return;
   if(p.condominio&&p.condominio!==unit)return;
   if(!uniq[e])uniq[e]={ean:e,product:p.produto||('EAN '+e)};
 });
 // Produtos que existem no estoque ou histórico também entram mesmo que faltem na base mestre.
 Object.keys(stockLedger).forEach(k=>{
   const sep=k.indexOf('|');if(sep<0)return;
   const u=k.slice(0,sep),e=k.slice(sep+1);if(u!==unit||!e||uniq[e])return;
   const p=masterProduct(e);uniq[e]={ean:e,product:p?p.produto:('EAN '+e)};
 });
 return Object.values(uniq);
}
function replStatus(avg,min,ideal,current,groupStatus){
 if(groupStatus)return groupStatus;
 if(avg<=0)return 'SEM_GIRO';
 if(current<=min)return 'REPOR';
 if(current<ideal)return 'ATENCAO';
 return 'OK';
}
async function calculateReplenishment(){
 const weeks=Number(valueFast('replWeeks'))||12,minFactor=Number(valueFast('replMinFactor'))||1,maxFactor=Number(valueFast('replMaxFactor'))||1.2,unitFilter=valueFast('replUnit')||TOTAL_UNIT,supplierFilter=valueFast('replSupplier')||'',salesMap=salesForReplenishment(weeks,unitFilter),members=[];
 replenishmentUnits(unitFilter).forEach(unit=>{const by={};replenishmentProductsForUnit(unit).forEach(p=>{const sale=salesMap[unit+'|'+p.ean]||{unit,ean:p.ean,product:p.product,weeks:{},total:0};by[p.ean]={...sale,product:p.product,current:currentStockFor(unit,p.ean),group:demandGroupFor(p.ean),supplier:supplierFor(p.ean)}});Object.values(salesMap).filter(x=>x.unit===unit).forEach(s=>{if(!by[s.ean])by[s.ean]={...s,current:currentStockFor(unit,s.ean),group:demandGroupFor(s.ean),supplier:supplierFor(s.ean)}});members.push(...Object.values(by))});
 let rows=await workerCalc('replenishment-grouped',{members,weeks,minFactor,maxFactor}),q=searchNorm(valueFast('replSearch')),statusFilter=valueFast('replStatus');rows=rows.filter(x=>(!supplierFilter||x.supplier===supplierFilter)&&(!statusFilter||x.status===statusFilter)&&(!q||searchNorm([x.product,x.ean,x.demandGroup,x.supplier].join(' ')).includes(q)));const order={REPOR:0,ATENCAO:1,OK:2,SEM_GIRO:3};rows.sort((a,b)=>(order[a.status]??9)-(order[b.status]??9)||(a.supplier||'').localeCompare(b.supplier||'')||a.unit.localeCompare(b.unit)||String(a.demandGroup).localeCompare(String(b.demandGroup))||a.product.localeCompare(b.product));return rows;
}
function refreshReplFilters(){
 fillAnalysisUnitSelect('replUnit');
 const sel=document.getElementById('replSupplier'),prev=sel.value;
 const sups=['',...Array.from(new Set(Object.values(supplierMap).filter(Boolean))).sort()];
 sel.innerHTML=sups.map(x=>`<option value="${x}">${x||'Todos os fornecedores'}</option>`).join('');
 if(sups.includes(prev))sel.value=prev;
}
function replStatusLabel(s){return s==='REPOR'?'REPOR':s==='ATENCAO'?'ATENÇÃO':s==='SEM_GIRO'?'SEM GIRO':'OK'}
async function renderReplenishment(){
 refreshReplFilters();
 const data=await calculateReplenishment();lastReplenishment=data;
 const alerts=data.filter(x=>x.status==='REPOR'&&x.suggested>0);
 document.getElementById('replAlerts').textContent=alerts.length.toLocaleString('pt-BR');
 document.getElementById('replUnits').textContent=alerts.reduce((a,x)=>a+x.suggested,0).toLocaleString('pt-BR');
 document.getElementById('replNoSupplier').textContent=new Set(alerts.filter(x=>x.supplier==='SEM FORNECEDOR').map(x=>x.ean)).size.toLocaleString('pt-BR');
 document.getElementById('replSkus').textContent=data.length.toLocaleString('pt-BR');

 const groups={};
 data.forEach(x=>{const k=x.unit+'|||'+x.demandGroup;if(!groups[k])groups[k]=[];groups[k].push(x)});
 const out=Object.entries(groups).map(([k,items])=>{
   const [unit,gname]=k.split('|||'),sample=items[0],isGroup=gname!=='INDIVIDUAL';
   const groupInfo=isGroup?`<div class="replGroupMetrics"><span>Estoque grupo <b>${sample.groupCurrent}</b></span><span>Ideal grupo <b>${sample.groupIdeal}</b></span><span>Pico grupo <b>${Number(sample.groupPeak||0).toFixed(0)}</b></span><span>Status <b class="replStatus ${sample.groupStatus}">${replStatusLabel(sample.groupStatus)}</b></span></div>`:'';
   const rows=items.map(x=>`<div class="replFullRow ${x.status}">
     <div><b>${x.product}</b><br><small>EAN ${x.ean}<br>${x.supplier||'SEM FORNECEDOR'}</small></div>
     <div><b>${x.demandGroup}</b>${x.groupShare!=null?`<br><small>${(x.groupShare*100).toFixed(1).replace('.',',')}% do grupo</small>`:''}</div>
     <div class="replnum">${x.avgWeekly.toFixed(1).replace('.',',')}<br><small>média/sem.</small></div>
     <div class="replnum">${Number(x.peakWeekly||0).toFixed(1).replace('.',',')}<br><small>pico</small></div>
     <div class="replnum">${x.minStock}<br><small>mínimo</small></div>
     <div class="replnum">${x.current}<br><small>atual</small></div>
     <div class="replnum"><b>${x.idealStock}</b><br><small>ideal</small></div>
     <div class="replnum">${x.suggested?'<b>'+x.suggested+'</b>':'0'}<br><small>repor</small></div>
     <div><span class="replStatus ${x.status}">${replStatusLabel(x.status)}</span>${x.coverage!==null?`<br><small>${x.coverage.toFixed(1).replace('.',',')} sem.</small>`:''}</div>
   </div>`).join('');
   return `<div class="replgroup"><div class="replhead">${unit} • ${gname}</div>${groupInfo}<div class="replFullRow replHeader"><b>Produto / EAN</b><b>Grupo</b><b>Média</b><b>Pico</b><b>Mín.</b><b>Atual</b><b>Ideal</b><b>Repor</b><b>Status</b></div>${rows}</div>`;
 }).join('');
 const flatRows=data;
 renderHtmlChunks(document.getElementById('replTable'),flatRows,x=>`<div class="replFullRow ${x.status}">
   <div><b>${x.product}</b><br><small>EAN ${x.ean}<br>${x.supplier||'SEM FORNECEDOR'}</small></div>
   <div><b>${x.demandGroup}</b>${x.groupShare!=null?`<br><small>${(x.groupShare*100).toFixed(1).replace('.',',')}% do grupo</small>`:''}</div>
   <div class="replnum">${x.avgWeekly.toFixed(1).replace('.',',')}<br><small>média/sem.</small></div>
   <div class="replnum">${Number(x.peakWeekly||0).toFixed(1).replace('.',',')}<br><small>pico</small></div>
   <div class="replnum">${x.minStock}<br><small>mínimo</small></div>
   <div class="replnum">${x.current}<br><small>atual</small></div>
   <div class="replnum"><b>${x.idealStock}</b><br><small>ideal</small></div>
   <div class="replnum">${x.suggested?'<b>'+x.suggested+'</b>':'0'}<br><small>repor</small></div>
   <div><span class="replStatus ${x.status}">${replStatusLabel(x.status)}</span>${x.coverage!==null?`<br><small>${x.coverage.toFixed(1).replace('.',',')} sem.</small>`:''}</div>
 </div>`,{initial:80,step:80,infoId:'replRowsInfo',moreId:'replShowMore'});
}
