function replenishmentCsv(){
 const rows=[['Fornecedor','Condomínio','Grupo de demanda','EAN','Produto','Venda média semanal','Pico mensurado','Estoque mínimo','Estoque atual','Estoque ideal','Cobertura semanas','Status','Quantidade a repor']];
 lastReplenishment.filter(x=>x.alert&&x.suggested>0).forEach(x=>rows.push([x.supplier,x.unit,x.demandGroup||'INDIVIDUAL',x.ean,x.product,x.avgWeekly.toFixed(2),x.peakWeekly.toFixed(2),x.minStock,x.current,x.idealStock,x.coverage===null?'':x.coverage.toFixed(2),replStatusLabel(x.status),x.suggested]));
 let esc=s=>'"'+String(s??'').replaceAll('"','""')+'"';
 return '\ufeff'+rows.map(r=>r.map(esc).join(';')).join('\r\n');
}
