let monthlyClosings={};
let paymentHistory=[];
function closingKey(month,unit){return month+'|'+(unit||'TODAS')}
function monthlyMetrics(month,unit=''){
 const rows=analysisSalesRows().filter(x=>rowMonth(x)===month&&(!unit||unit===TOTAL_UNIT||x.unit===unit)&&!String(x.unit).toLowerCase().includes('cd - estoque central'));
 const revenue=rows.reduce((a,x)=>a+(Number(x.value)||0),0),unitsSold=rows.reduce((a,x)=>a+(Number(x.qty)||0),0),tickets=new Set(rows.map(x=>x.unit+'|'+normalizeDateTime(x.datetime))).size;
 let cmv=0;rows.forEach(x=>{const p=saleMasterProduct(x),e=p?p.ean:(x.ean||x.code);if(e)cmv+=(Number(x.qty)||0)*(Number(gs(x.unit,e).avgCost)||0)});const gross=revenue-cmv;
 return{month,unit:unit||TOTAL_UNIT,revenue,unitsSold,tickets,avgTicket:tickets?revenue/tickets:0,cmv,gross,grossMargin:revenue?gross/revenue*100:0};
}
function saveMonthlyClosing(month){if(!month)return;const us=Array.from(new Set(analysisSalesRows().filter(x=>rowMonth(x)===month).map(x=>x.unit).filter(Boolean)));monthlyClosings[closingKey(month,'')]=monthlyMetrics(month,TOTAL_UNIT);us.forEach(u=>monthlyClosings[closingKey(month,u)]=monthlyMetrics(month,u));persistState('monthlyClosings',monthlyClosings);}
function renderMonthlyHistory(){
 fillAnalysisUnitSelect('monthlyUnit');
 const u=document.getElementById('monthlyUnit').value||TOTAL_UNIT,by={};

 if(optimizedHistoryReady&&historicalUnitDayRows.length){
   historicalUnitDayRows.forEach(x=>{
     if(u!==TOTAL_UNIT&&x.unit!==u)return;
     const m=x.date.slice(0,7);
     if(!by[m])by[m]={revenue:0,unitsSold:0,tickets:0,cmv:0};
     by[m].revenue+=Number(x.value)||0;by[m].unitsSold+=Number(x.qty)||0;by[m].tickets+=Number(x.tickets)||0;
   });
 }else{
   ['2026-04','2026-05','2026-06','2026-07'].forEach(m=>{
     const sm=salesMetrics(u,m+'-01',m+'-31');by[m]={revenue:sm.revenue,unitsSold:sm.unitsSold,tickets:sm.tickets,cmv:sm.cmv};
   });
 }
 const rows=Object.entries(by).sort((a,b)=>b[0].localeCompare(a[0]));
 document.getElementById('monthlyTable').innerHTML=rows.map(([m,x])=>{
   const avg=x.tickets?x.revenue/x.tickets:0,margin=x.revenue-x.cmv,pct=x.revenue?margin/x.revenue*100:0;
   return `<div class="monthlyrow"><b>${m}</b><span>${brl(x.revenue)}</span><span>${x.tickets.toLocaleString('pt-BR')}</span><span>${brl(avg)}</span><span>${brl(x.cmv)}</span><span>${pct.toFixed(1).replace('.',',')}%</span></div>`;
 }).join('')||'<small>Sem histórico.</small>';
}
