function salesRevenueForMonthUnit(month,unit){return monthlyMetrics(month,unit).revenue}
function paymentCalc(){const month=document.getElementById('payMonth').value,unit=document.getElementById('payUnit').value,revenue=salesRevenueForMonthUnit(month,unit),pct=parseMoney(document.getElementById('payCashPct').value),prev=parseMoney(document.getElementById('payPrevRead').value),curr=parseMoney(document.getElementById('payCurrRead').value),rate=parseMoney(document.getElementById('payEnergyRate').value),kwh=Math.max(0,curr-prev),cash=revenue*pct/100,energy=kwh*rate,total=cash+energy;document.getElementById('payRevenue').value=revenue.toFixed(2);document.getElementById('cashbackValue').textContent=brl(cash);document.getElementById('energyKwh').textContent=kwh.toFixed(2)+' kWh';document.getElementById('energyValue').textContent=brl(energy);document.getElementById('paymentTotal').textContent=brl(total);return{month,unit,revenue,cashbackPct:pct,cashbackValue:cash,previousReading:prev,currentReading:curr,kwh,energyRate:rate,energyValue:energy,total,note:document.getElementById('payNote').value.trim()}}
function latestPreviousReading(unit,month){const a=paymentHistory.filter(x=>x.unit===unit&&x.month<month).sort((a,b)=>b.month.localeCompare(a.month));return a.length?Number(a[0].currentReading)||0:0}
function prefillPayment(){const month=document.getElementById('payMonth').value,unit=document.getElementById('payUnit').value;if(!month||!unit)return;const x=paymentHistory.find(x=>x.month===month&&x.unit===unit);if(x){document.getElementById('payCashPct').value=x.cashbackPct||0;document.getElementById('payPrevRead').value=x.previousReading||0;document.getElementById('payCurrRead').value=x.currentReading||0;document.getElementById('payEnergyRate').value=x.energyRate||0;document.getElementById('payNote').value=x.note||''}else{document.getElementById('payPrevRead').value=latestPreviousReading(unit,month)||''}paymentCalc()}
function renderPaymentHistory(){fillUnitSelect('payHistoryUnit',true);const u=document.getElementById('payHistoryUnit').value||'',rows=paymentHistory.filter(x=>!u||x.unit===u).sort((a,b)=>b.month.localeCompare(a.month));document.getElementById('paymentHistory').innerHTML='<div class="payrow"><b>Mês</b><b>Condomínio</b><b>Cashback</b><b>kWh</b><b>Energia</b><b>Total</b></div>'+rows.map(x=>`<div class="payrow"><b>${x.month}</b><span>${x.unit}</span><span>${brl(x.cashbackValue)}</span><span>${x.kwh}</span><span>${brl(x.energyValue)}</span><b>${brl(x.total)}</b></div>`).join('')}
