async function autoFiscalLookup(e){e=norm(e);const f=getFiscal(e),p=fiscalProduct(e);f.checkedAt=new Date().toISOString();if(p.ncm||p.cest){f.ncm=norm(p.ncm).slice(0,8);f.cest=norm(p.cest).slice(0,7);f.status='ENCONTRADO';f.source='BASE_MESTRE/NF'}saveFiscal();if(API_URL){try{const r=await fetch(API_URL+'?action=fiscal_lookup&ean='+encodeURIComponent(e)+'&uf=SC&t='+Date.now());if(r.ok){const d=await r.json();if(d&&d.ok){f.ncm=norm(d.ncm||f.ncm).slice(0,8);f.cest=norm(d.cest||f.cest).slice(0,7);f.status=d.status||f.status;f.scStatus=d.scStatus||f.scStatus;f.source=d.source||f.source;f.checkedAt=new Date().toISOString();saveFiscal()}}}catch(err){}}renderFiscal();return f}
