window.lookupFiscalNow=e=>autoFiscalLookup(e);
window.editFiscal=e=>{const f=getFiscal(e),p=fiscalProduct(e);document.getElementById('fiscalEdit').style.display='block';document.getElementById('fiscalEditEan').value=e;document.getElementById('fiscalEditProduct').innerHTML='<b>'+p.produto+'</b><br><small>'+e+'</small>';document.getElementById('fiscalEditNcm').value=f.ncm||'';document.getElementById('fiscalEditCest').value=f.cest||'';document.getElementById('fiscalEditSc').value=f.scStatus||'PENDENTE';document.getElementById('fiscalEditSource').value=f.source||''}
(document.getElementById('saveFiscalReview')||{}).onclick=()=>{const e=norm(document.getElementById('fiscalEditEan').value),f=getFiscal(e);f.ncm=norm(document.getElementById('fiscalEditNcm').value).slice(0,8);f.cest=norm(document.getElementById('fiscalEditCest').value).slice(0,7);f.scStatus=document.getElementById('fiscalEditSc').value;f.status=f.ncm?'ENCONTRADO':'PENDENTE';f.source=document.getElementById('fiscalEditSource').value.trim()||'REVISAO_MANUAL';f.checkedAt=new Date().toISOString();saveFiscal();renderFiscal()}
(document.getElementById('fiscalSearch')||{}).oninput=renderFiscal;(document.getElementById('fiscalStatusFilter')||{}).onchange=renderFiscal;(document.getElementById('refreshFiscal')||{}).onclick=renderFiscal;
