let authState={token:localStorage.getItem('okeo_auth_token_v39')||'',user:null};
let syncQueue=[];

function backendUrl(){return 'https://script.google.com/macros/s/AKfycbxFBV9P3t0t4FAX4y83yPhQpQnDmLJzNsp4afqoD6NKXMBROOO6Zm-00fuWgqjrcvgq/exec'}
async function postBackend(action,data={},withToken=true){
 const url=backendUrl(); if(!url)throw new Error('Backend não configurado');
 const body={action,data}; if(withToken&&authState.token)body.token=authState.token;
 const r=await fetch(url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(body)});
 return await r.json();
}

function recordBackendFailure(action,e){
 recordDiagnostic('backend',e&&e.message?e.message:'Falha de comunicação',`Ação: ${safeDiagText(action)}`,'integracao');
}
async function getBackend(action,params={}){
 const u=new URL(backendUrl());u.searchParams.set('action',action);if(authState.token)u.searchParams.set('token',authState.token);
 Object.entries(params).forEach(([k,v])=>u.searchParams.set(k,v));
 const ctrl=new AbortController();const timer=setTimeout(()=>ctrl.abort(),12000);try{const r=await fetch(u.toString(),{cache:'no-store',signal:ctrl.signal});return await r.json()}finally{clearTimeout(timer)}
}
function queueSync(action,data){
 syncQueue.push({id:String(Date.now())+Math.random(),action,data,createdAt:new Date().toISOString()});
 persistState('syncQueue',syncQueue);flushSyncQueue();
}
async function flushSyncQueue(){
 if(!navigator.onLine||!backendUrl()||!authState.token||!syncQueue.length)return;
 const remain=[];for(const x of syncQueue){try{const r=await postBackend(x.action,x.data,true);if(!r.ok)throw 0}catch(e){remain.push(x)}}
 syncQueue=remain;persistState('syncQueue',syncQueue);
}
window.addEventListener('online',flushSyncQueue);

function applyRoleUI(){
 setTimeout(applySuiteScope,0);
 const role=(authState.user&&String(authState.user.role||'').toUpperCase())||'';
 document.querySelectorAll('[data-min-role]').forEach(el=>{
   const module=el.getAttribute('data-module')||'';
   let allowed=false;
   if(role==='ADMIN'){
     allowed=true;
   }else if(role==='OPERATIONAL'){
     allowed=(module==='inventario'||module==='nf');
   }
   el.style.setProperty('display',allowed?'':'none','important');
 });
 // Mantém apenas módulos autorizados no painel moderno
 document.querySelectorAll('.moduleCard').forEach(el=>{
   const module=el.getAttribute('data-module')||'';
   const allowed=role==='ADMIN'||(role==='OPERATIONAL'&&(module==='inventario'||module==='nf'));
   el.style.setProperty('display',allowed?'flex':'none','important');
 });
 // Elementos administrativos auxiliares
 document.querySelectorAll('[data-admin-only]').forEach(el=>{
   el.style.setProperty('display',role==='ADMIN'?'':'none','important');
 });
 const banner=document.getElementById('roleAccessBanner');if(banner)banner.style.display=(role==='OPERATIONAL'?'block':'none');
 const lbl=document.getElementById('currentUserLabel');
 if(lbl&&authState.user)lbl.textContent=`• ${authState.user.name||authState.user.username||''} (${role==='ADMIN'?'Administrador':'Operacional'})`;
}
function canAccessModule(name){
 if(!suiteModuleAllowed(name))return false;
 const role=(authState.user&&String(authState.user.role||'').toUpperCase())||'';
 if(role==='ADMIN')return true;
 if(role==='OPERATIONAL')return name==='inventario'||name==='nf';
 return false;
}
async function validateSession(){
 if(!authState.token)return false;
 try{const r=await getBackend('session');if(r.ok){authState.user=r.user;applyRoleUI();return true}}catch(e){}
 localStorage.removeItem('okeo_auth_token_v39');localStorage.removeItem('okeo_session_confirmed_v435');return false;
}

