async function sha256Hex(text){
 const data=new TextEncoder().encode(String(text));
 const buf=await crypto.subtle.digest('SHA-256',data);
 return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
}
async function loginWithChallenge(username,password){
 const fetchPublic=async(action,params={})=>{
   const u=new URL(OKEO_DEFAULT_BACKEND);
   u.searchParams.set('action',action);
   u.searchParams.set('_ts',Date.now().toString()+'_'+Math.random().toString(36).slice(2));
   Object.entries(params).forEach(([k,v])=>u.searchParams.set(k,v));
   const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),12000);
   try{
     const resp=await fetch(u.toString(),{cache:'no-store',signal:ctrl.signal});
     return await resp.json();
   }finally{clearTimeout(timer)}
 };
 const c=await fetchPublic('login_challenge',{username});
 if(!c||!c.ok)throw new Error('CHALLENGE: '+((c&&c.error)||'Não foi possível iniciar o login.'));
 const passHash=await sha256Hex(String(c.salt||'')+'|'+String(password||''));
 const proof=await sha256Hex(String(c.nonce||'')+'|'+passHash);
 const r=await fetchPublic('login_verify',{username,nonce:c.nonce,proof});
 if(!r||!r.ok)throw new Error('VERIFY: '+((r&&r.error)||'Usuário ou senha inválidos.'));
 return r;
}
async function saveUserWithHash(data){
 const salt=(crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random()).replace(/-/g,'');
 const passwordHash=await sha256Hex(salt+'|'+String(data.password||''));
 return await getBackend('user_save_hashed',{username:data.username,name:data.name,role:data.role,active:data.active!==false?'1':'0',salt,passwordHash});
}

window.okeoCompleteLogin=async function(r){
 try{
   window.__OKEO_LOGIN_ACTIVE=true;window.__OKEO_AUTH_READY=true;
   authState={token:r.token,user:r.user};
   localStorage.setItem('okeo_auth_token_v39',r.token);
   localStorage.setItem('okeo_session_confirmed_v435','1');
   document.getElementById('loginOverlay').style.display='none';
   const btn=document.getElementById('loginBtn');if(btn)btn.disabled=false;
   applyRoleUI();setAnalysisDefaults();
   await hydrateOperationalState();
   showTab(OKEO_SUITE_DEFAULT);markBootComplete();
   setTimeout(()=>{onlineStatus();renderStorageHealth()},300);
   setTimeout(()=>{try{flushSyncQueue()}catch(e){}},1500);
 }catch(e){console.warn('okeoCompleteLogin',e)}
}
