function renderHomeDashboard(){
 try{
   if(!historicalUnitDayRows.length)return;
   const latest=historicalUnitDayRows.map(x=>x.date).sort().pop()?.slice(0,7)||'';
   const rows=historicalUnitDayRows.filter(x=>x.date.startsWith(latest));
   const revenue=rows.reduce((a,x)=>a+Number(x.value||0),0),sold=rows.reduce((a,x)=>a+Number(x.qty||0),0),tickets=rows.reduce((a,x)=>a+Number(x.tickets||0),0),avg=tickets?revenue/tickets:0;
   const st=totalStockMetrics(),set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};
   set('homeRevenue',brl(revenue));set('homeTicket',brl(avg));set('homeUnitsSold',sold.toLocaleString('pt-BR'));set('homeMargin','—');
   set('homeStock',st.qty.toLocaleString('pt-BR'));set('homeConsolRevenue',brl(revenue));set('homeConsolSold',sold.toLocaleString('pt-BR'));set('homeConsolTicket',brl(avg));set('homeConsolMargin','—');
 }catch(e){}
}

