// Totalizador
function allSalesUnits(){return units.filter(u=>u!==TOTAL_UNIT&&!String(u).toLowerCase().includes('cd - estoque central'))}
function stockUnitsIncludingCd(){return units.filter(u=>u!==TOTAL_UNIT)}
function fillUnitSelectWithTotal(id,blank=false,includeCd=true){const s=document.getElementById(id);if(!s)return;const base=(includeCd?stockUnitsIncludingCd():allSalesUnits()).filter(u=>u!==TOTAL_UNIT),list=[TOTAL_UNIT,...Array.from(new Set(base))],prev=s.value;s.innerHTML=list.map(u=>`<option value="${u}">${u}</option>`).join('');s.value=(prev&&list.includes(prev))?prev:TOTAL_UNIT}
function fillAnalysisUnitSelect(id){fillUnitSelectWithTotal(id,false,false)}
function totalStockMetrics(){
 let qty=0,value=0,weighted=0;
 stockUnitsIncludingCd().forEach(u=>Object.entries(stockLedger).forEach(([k,s])=>{
   if(k.startsWith(u+'|')){qty+=Number(s.qty)||0;value+=(Number(s.qty)||0)*(Number(s.avgCost)||0);weighted+=(Number(s.qty)||0)*(Number(s.avgCost)||0)}
 }));
 return {qty,value,avg:qty?weighted/qty:0};
}


async function runSystemSelfTest(){
 const out=[],push=(name,ok,detail='')=>out.push({name,ok,detail});
 try{push('JavaScript',true,'Motor ativo')}catch(e){push('JavaScript',false,e.message)}
 try{
   const h=await storageHealth();push('Armazenamento',!!h,h?`${bytesHuman(h.usage)} / ${bytesHuman(h.quota)}`:'API indisponível');
 }catch(e){push('Armazenamento',false,e.message)}
 try{
   const c=await fetch(OKEO_DEFAULT_BACKEND+'?action=login_challenge&username=__healthcheck__&_ts='+Date.now(),{cache:'no-store'});
   const j=await c.json();push('Base Central',!!j,'HTTP/JSON respondendo');
 }catch(e){push('Base Central',false,e.message)}
 try{push('Cache PWA','caches' in window,'Cache API')}catch(e){push('Cache PWA',false,e.message)}
 try{push('Service Worker','serviceWorker' in navigator,'Suporte do navegador')}catch(e){push('Service Worker',false,e.message)}
 try{push('Criptografia',!!(crypto&&crypto.subtle),'SHA-256 disponível')}catch(e){push('Criptografia',false,e.message)}
 const box=document.getElementById('selfTestResults');
 if(box)box.innerHTML=out.map(x=>`<div class="selfTestRow"><span>${x.name}<small>${x.detail}</small></span><b class="${x.ok?'testOk':'testBad'}">${x.ok?'OK':'FALHA'}</b></div>`).join('');
 out.filter(x=>!x.ok).forEach(x=>recordDiagnostic?.('selftest',x.name+' falhou',x.detail,'diagnostico'));
 return out;
}
