(async()=>{
 try{
   const token=localStorage.getItem('okeo_auth_token_v39')||'';
   if(!token){if(!window.__OKEO_LOGIN_ACTIVE)document.getElementById('loginOverlay').style.display='flex';return}
   if(window.__OKEO_LOGIN_ACTIVE||localStorage.getItem('okeo_session_confirmed_v435')==='1'){
     window.__OKEO_AUTH_READY=true;document.getElementById('loginOverlay').style.display='none';
     const saved=localStorage.getItem('okeo_auth_user_v434');
     if(saved&&!authState.user){try{authState={token,user:JSON.parse(saved)}}catch(e){}}
     if(authState.user){
       applyRoleUI();setAnalysisDefaults();await hydrateOperationalState();
       showTab(OKEO_SUITE_DEFAULT);markBootComplete();
       setTimeout(()=>{onlineStatus();renderStorageHealth()},300);
       setTimeout(()=>{try{flushSyncQueue()}catch(e){}},1500);
     }
     return;
   }
   const valid=await validateSession();if(window.__OKEO_LOGIN_ACTIVE)return;
   if(valid){
     window.__OKEO_AUTH_READY=true;document.getElementById('loginOverlay').style.display='none';
     applyRoleUI();setAnalysisDefaults();await hydrateOperationalState();
     showTab(OKEO_SUITE_DEFAULT);markBootComplete();setTimeout(()=>{onlineStatus();renderStorageHealth()},300);
   }else if(!window.__OKEO_LOGIN_ACTIVE){
     localStorage.removeItem('okeo_auth_token_v39');localStorage.removeItem('okeo_session_confirmed_v435');
     document.getElementById('loginOverlay').style.display='flex';
   }
 }catch(e){
   if(!window.__OKEO_LOGIN_ACTIVE&&!window.__OKEO_AUTH_READY)document.getElementById('loginOverlay').style.display='flex';
 }
})();
